ADD R2, R3
JUMP check_wall
move_right:
INC R2
check_wall:
MOVI R4, 65536
ADD R4, R2
LDB R4, [R4]
MOVI R3, 35
CMP R4, R3
JZ blocked
MOV R0, R2
